/* Top Action Buttons */
.categoriesContainer {
  background-color: ${theme.colors.background.primary};
  display: flex;
  justify-content: space-around;
}

.catBtn {
  width: 100%;
  padding: 1%;
  cursor: pointer;
  justify-content: center;
  text-align: center;
  background-color: ${theme.colors.background.secondary};
}

.catBtn:hover {
  padding: 1%;
  cursor: pointer;
  color: ${theme.colors.background.primary};
  background-color:  ${theme.colors.primary.main};
}

#treeSearch {
  width: 100%;
}

#collBtn {
  width: 100%;
  background-color: ${theme.colors.background.secondary};
  color: ${theme.colors.text.primary};
  padding: 5px;
  text-align: center;
  cursor: pointer;
}

#collBtn:hover {
  color: ${theme.colors.background.primary};
  background-color:  ${theme.colors.primary.main};
}

/* Base Tree */
.tree {
  width: 100%;
  font-family: monospace;
  background-color: ${theme.colors.background.primary};
}

.hidden {
  display: none;
}

/* Sections */
.key {
  font-weight: 600;
  color: ${theme.colors.text.primary};
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 4px;
  transition: background-color 0.2s ease;
}

.key:hover {
  color:  ${theme.colors.primary.main}
}

.children { 
  margin-left: 20px;
}

.expand-icon {
  display: inline-block;
  width: 14px;
  text-align: center;
}

/* Leafs */
.leaf {
  border-left:dashed;
  border-radius: 2px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0px 20px;
}

.leaf:hover {
  background-color: ${theme.colors.background.secondary};
  cursor: pointer;
}

.leaf:hover .nameText {
  color: ${theme.colors.primary.main}
}

.leaf:hover .btnHolder {
  display: inline-flex;
}

.nameText {
  color: ${theme.colors.text.primary};
  font-weight: bold;
  cursor: pointer;
  padding: 1px;
  transition: background-color 0.2s ease;
}

.btnHolder {
  display: none;
  width: 100px;
  height: 20px;
  justify-content: right;
  align-items: center;
}

.leafBtn {
  display: flex;
  padding: 0;
  width: 20px;
  height: 20px;
  margin-right: 5px;
  border-radius: 2px;
  background-color: ${theme.colors.background.primary};
  color: ${theme.colors.primary.main};
  font-size: 15px;
  font-weight: bold;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.leafBtn:hover {
  background-color:  ${theme.colors.primary.main};
  color: ${theme.colors.text.primary};
}

